/** One admitted turn with a pending (unpublished) native tool authority. */
async function admitTurn(runId: string) {
  const admission = admissionApi.prepareAgentRunAdmission({
    cfg: cfg as never,
    facts: {
      runId,
      agentId: "main",
      ingress: { kind: "system", boundary: "proof-197126", state: "present" },
