    },
    body: JSON.stringify({
      jsonrpc: "2.0",
      id: 1,
      method: "tools/call",
      params: { name, arguments: args },
    }),
  });
  const text = await response.text();
  return { status: response.status, text, elapsedMs: Math.round(performance.now() - startedAt) };
}

