import { spawnSync } from "node:child_process";
import { randomBytes } from "node:crypto";
import fs from "node:fs";
import net from "node:net";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { Worker } from "node:worker_threads";

// A main-thread setInterval provably does not fire during a synchronous
// jiti/tsx module compile, and a silent proof reads as a hung proof.
const heartbeat = new Worker(
  `const { writeSync } = require("node:fs");
   let n = 0;
   setInterval(() => { writeSync(2, "[proof] still running (" + (++n) * 5 + "s)\\n"); }, 5000).unref?.();
   setInterval(() => {}, 1 << 30);`,
  { eval: true, stdout: false },
);

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

let passed = 0;
let failed = 0;
const notes: string[] = [];

function check(label: string, actual: unknown, expected: unknown): void {
  if (actual === expected) {
    passed += 1;
    console.log(`  PASS ${label}: ${String(actual)}`);
  } else {
    failed += 1;
    console.log(`  FAIL ${label}: expected ${String(expected)}, got ${String(actual)}`);
  }
}

const tempRoots: string[] = [];

function tempDir(prefix: string): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), prefix));
  tempRoots.push(dir);
  return dir;
}

function removeTempRoots(): void {
  for (const dir of tempRoots.splice(0)) {
    try {
      fs.rmSync(dir, { recursive: true, force: true });
    } catch (error: unknown) {
      console.log(`  cleanup WARN: could not remove ${dir}: ${String(error)}`);
    }
  }
}

async function freePort(): Promise<number> {
  return await new Promise<number>((resolve, reject) => {
    const server = net.createServer();
    server.unref();
    server.on("error", reject);
    server.listen(0, "127.0.0.1", () => {
      const address = server.address();
      const port = typeof address === "object" && address ? address.port : 0;
      server.close(() => {
        if (port === 0) {
          reject(new Error("could not reserve a loopback port"));
          return;
        }
        resolve(port);
      });
    });
  });
}

/**
 * Writes a real non-bundled plugin whose manifest declares startup activation,
 * which is what makes a Gateway startup plan select it once it is installed.
 */
function writeRealPlugin(params: { id: string; registerBody: string }): {
  dir: string;
  file: string;
} {
  const dir = tempDir(`proof-197115-${params.id}-`);
  const file = path.join(dir, "index.cjs");
  fs.writeFileSync(
    file,
    `module.exports = { id: ${JSON.stringify(params.id)}, register(api) {\n${params.registerBody}\n} };\n`,
    "utf-8",
  );
  fs.writeFileSync(
    path.join(dir, "package.json"),
    `${JSON.stringify(
      {
        name: params.id,
        version: "1.0.0",
        main: "index.cjs",
        private: true,
        openclaw: { extensions: ["./index.cjs"] },
      },
      null,
      2,
    )}\n`,
    "utf-8",
  );
  fs.writeFileSync(
    path.join(dir, "openclaw.plugin.json"),
    `${JSON.stringify(
      {
        id: params.id,
        name: params.id,
        version: "1.0.0",
        main: "index.cjs",
        activation: { onStartup: true },
        configSchema: { type: "object", properties: {} },
      },
      null,
      2,
    )}\n`,
    "utf-8",
  );
  return { dir, file };
}

/**
 * Tees every byte the process would print into a buffer. The Gateway's
 * subsystem logger ends up on stdout/stderr, so this is the cheapest place to
 * read what an operator watching startup sees without replacing the logger.
 */
function captureOutput(): { stop: () => string } {
  let buffer = "";
  const originals = {
    stdout: process.stdout.write.bind(process.stdout),
    stderr: process.stderr.write.bind(process.stderr),
  };
  const record = (chunk: unknown): void => {
    buffer += typeof chunk === "string" ? chunk : String(chunk);
  };
  process.stdout.write = ((chunk: unknown, ...rest: unknown[]) => {
    record(chunk);
    return (originals.stdout as (...args: unknown[]) => boolean)(chunk, ...rest);
  }) as typeof process.stdout.write;
  process.stderr.write = ((chunk: unknown, ...rest: unknown[]) => {
    record(chunk);
    return (originals.stderr as (...args: unknown[]) => boolean)(chunk, ...rest);
  }) as typeof process.stderr.write;
  return {
    stop: () => {
      process.stdout.write = originals.stdout as typeof process.stdout.write;
      process.stderr.write = originals.stderr as typeof process.stderr.write;
      return buffer;
    },
  };
}

const GROUPED_SUMMARY = /\[plugins\] hook registrations blocked for (\d+) plugin\(s\)/;

function countCompactBlockedHooks(line: string | undefined): number {
  if (!line) {
    return 0;
  }
  const match = /(\d+) blocked hooks?\b/.exec(line);
  return match ? Number(match[1]) : 0;
}

function occurrences(haystack: string, needle: string): number {
  return needle ? haystack.split(needle).length - 1 : 0;
}

/** Writes a throwaway state dir plus the openclaw.json the CLI and Gateway read. */
function prepareStateDir(params: {
  pluginId: string;
  allowConversationAccess?: boolean;
  gatewayPort?: number;
}): { stateDir: string; configPath: string; homeDir: string } {
  const homeDir = tempDir("proof-197115-home-");
  const stateDir = path.join(homeDir, ".openclaw");
  fs.mkdirSync(stateDir, { recursive: true });
  const configPath = path.join(stateDir, "openclaw.json");
  const config: Record<string, unknown> = {
    ...(params.gatewayPort == null
      ? {}
      : { gateway: { port: params.gatewayPort, bind: "loopback", controlUi: { enabled: false } } }),
    plugins: {
      enabled: true,
      slots: { memory: "none" },
      ...(params.allowConversationAccess == null
        ? {}
        : {
            entries: {
              [params.pluginId]: {
                enabled: true,
                hooks: { allowConversationAccess: params.allowConversationAccess },
              },
            },
          }),
    },
  };
  fs.writeFileSync(configPath, `${JSON.stringify(config, null, 2)}\n`, "utf-8");
  return { stateDir, configPath, homeDir };
}

/** Runs the REAL CLI entrypoint in a child process against a prepared state dir. */
function runRealCli(params: {
  args: string[];
  stateDir: string;
  configPath: string;
  homeDir: string;
  workspaceDir: string;
}): { stdout: string; stderr: string; status: number | null } {
  const result = spawnSync(
    process.execPath,
    ["--import", "./scripts/tsx.mjs", "src/entry.ts", ...params.args],
    {
      cwd: repoRoot,
      encoding: "utf-8",
      timeout: 300_000,
      env: {
        ...process.env,
        HOME: params.homeDir,
        OPENCLAW_STATE_DIR: params.stateDir,
        OPENCLAW_CONFIG_PATH: params.configPath,
        OPENCLAW_WORKSPACE_DIR: params.workspaceDir,
        OPENCLAW_DISABLE_BUNDLED_PLUGINS: "1",
        OPENCLAW_DISABLE_UPDATE_CHECK: "1",
        NO_COLOR: "1",
        FORCE_COLOR: "0",
        CI: "1",
      },
    },
  );
  return { stdout: result.stdout ?? "", stderr: result.stderr ?? "", status: result.status };
}

async function main(): Promise<number> {
  console.log(
    "proof-197115: blocked typed-hook registrations on a REAL Gateway startup, in /status, and in the real CLI",
  );

  const pluginId = "proof-blocked-hook";
  const plugin = writeRealPlugin({
    id: pluginId,
    registerBody: `    api.on("before_agent_reply", () => undefined);`,
  });
  const gatewayPort = await freePort();
  const blocked = prepareStateDir({ pluginId, gatewayPort });
  console.log(`  worktree:   ${repoRoot}`);
