  // ---------------------------------------------------------------- scenario 1
  console.log("\n=== 1. REAL GATEWAY STARTUP + /status + /status plugins (P2) ===");
  process.env.HOME = blocked.homeDir;
  process.env.OPENCLAW_STATE_DIR = blocked.stateDir;
  process.env.OPENCLAW_CONFIG_PATH = blocked.configPath;
  process.env.OPENCLAW_WORKSPACE_DIR = plugin.dir;
  process.env.OPENCLAW_DISABLE_BUNDLED_PLUGINS = "1";
  process.env.OPENCLAW_DISABLE_UPDATE_CHECK = "1";
  delete process.env.OPENCLAW_BUNDLED_PLUGINS_DIR;

  const { startGatewayServer } = await import("../src/gateway/server.js");
  const { getActivePluginRegistry } = await import("../src/plugins/runtime.js");
